mapper.select:
SELECT t_sprinkler.*,
t_usable_sprinkler.allocate_limitation
FROM t_sprinkler
LEFT JOIN t_usable_sprinkler ON t_sprinkler.sprinkler_id = t_usable_sprinkler.sprinkler_id

    t_sprinkler.deleted_flag = #{queryForm.deletedFlag}

        AND INSTR(t_sprinkler.purchase_date_contract_number,#{queryForm.purchaseDateContractNumber})


        AND INSTR(t_sprinkler.sprinkler_model,#{queryForm.sprinklerModel})


        AND INSTR(t_sprinkler.sprinkler_serial,#{queryForm.sprinklerSerial})


        AND DATE_FORMAT(t_sprinkler.shipping_date, '%Y-%m-%d') >= #{queryForm.shippingDateStartTime}


        AND DATE_FORMAT(t_sprinkler.shipping_date, '%Y-%m-%d') <= #{queryForm.shippingDateEndTime}


        AND DATE_FORMAT(t_sprinkler.warehouse_date, '%Y-%m-%d') >= #{queryForm.warehouseDateStartTime}


        AND DATE_FORMAT(t_sprinkler.warehouse_date, '%Y-%m-%d') <= #{queryForm.warehouseDateEndTime}


        AND DATE_FORMAT(t_sprinkler.allocate_date, '%Y-%m-%d') >= #{queryForm.allocateDateStartTime}


        AND DATE_FORMAT(t_sprinkler.allocate_date, '%Y-%m-%d') <= #{queryForm.allocateDateEndTime}


        AND INSTR(t_sprinkler.allocate_user,#{queryForm.allocateUser})


        AND INSTR(t_sprinkler.allocate_purpose,#{queryForm.allocatePurpose})


        AND INSTR(t_sprinkler.allocate_position,#{queryForm.allocatePosition})


        AND INSTR(t_sprinkler.history,#{queryForm.history})


        AND t_sprinkler.status = #{queryForm.status}


        AND t_sprinkler.is_new = #{queryForm.isNew}


        AND INSTR(t_sprinkler.sprinkler_detail,#{queryForm.sprinklerDetail})


        AND t_sprinkler.disabled_flag = #{queryForm.disabledFlag}



        AND DATE_FORMAT(t_usable_sprinkler.ret_warehouse_date, '%Y-%m-%d') >= #{joinForm.retWarehouseDateStartTime}


        AND DATE_FORMAT(t_usable_sprinkler.ret_warehouse_date, '%Y-%m-%d') <= #{joinForm.retWarehouseDateEndTime}



        AND INSTR(t_usable_sprinkler.allocate_limitation,#{joinForm.allocateLimitation})



        AND INSTR(t_usable_sprinkler.allocate_note1,#{joinForm.allocateNote1})


        ORDER BY create_time DESC
